import { SmartContract, assert, checkSig, PubKey, Sig } from 'runar-lang';

class DupPublic extends SmartContract {
  readonly pk: PubKey;

  constructor(pk: PubKey) {
    super(pk);
    this.pk = pk;
  }

  public withdraw(sig: Sig) {
    assert(checkSig(sig, this.pk));
  }

  public withdraw(x: bigint) {
    assert(x == x);
  }
}

